import"./chunk-2NFLSA4Y.js";var r={circuits:{theory:{concept:"[[An electric circuit is a closed chain of a current source (a battery), connecting wires and consumers such as bulbs, through which an electric current flows.]] Consumers can be connected in series \u2014 one after another, so the same current passes through all of them \u2014 or in parallel \u2014 each on its own branch between the same two points, so each gets the same voltage. The type of connection decides how brightly the bulbs shine and what happens when one of them goes out."},section:{circuit:{title:"A closed circuit",text:"A battery pushes electric charges around a circuit: out of one terminal, through the wires and bulbs, and back into the other. The current I tells how much charge passes each second (1 A = 1 C/s). It flows only if the path is closed \u2014 a broken wire or an unscrewed bulb stops it. By convention current flows from + to \u2212; the electrons in the wires actually move the other way."},series:{title:"Series: one path",text:"[[In a series circuit there is only one path, so the same current flows through every bulb.]] The resistances add up: R = R\u2081 + R\u2082 + R\u2083, so more bulbs mean less current and dimmer light. The battery voltage is shared between the bulbs: U = U\u2081 + U\u2082 + U\u2083, the bigger share going to the bigger resistance. If one bulb goes out, the path is broken and they all go dark \u2014 like old strings of fairy lights."},parallel:{title:"Parallel: several paths",text:"[[In a parallel circuit each bulb has its own path between the same two points, so each gets the full battery voltage and shines as brightly as if it were alone.]] The currents add up: I = I\u2081 + I\u2082 + I\u2083. Adding a branch lowers the total resistance (1/R = 1/R\u2081 + 1/R\u2082 + 1/R\u2083), so the battery delivers more current. If one bulb goes out, the others keep shining \u2014 that is why the sockets in a house are wired in parallel."},mixed:{title:"Mixed circuits",text:"Real circuits combine both. Here bulb 1 is in series with a parallel pair, bulbs 2 and 3. All the current passes bulb 1, then splits between bulbs 2 and 3 and joins again. Work it out step by step: first replace the parallel pair by one resistance, then add the series part."},brightness:{title:"How bright?",text:"A bulb's brightness depends on its power P = U \xB7 I = I\xB2 \xB7 R \u2014 the energy it turns into light and heat each second. Three equal bulbs in series each get a third of the voltage and a third of the current, so they shine with only a ninth of the power they would have alone. In parallel each shines at full power, but the battery has to deliver three times the current and runs down faster."},battery:{title:"The battery's own resistance",text:"A real battery has an internal resistance r. When current flows, part of the voltage is lost inside it: the voltage at its terminals is U = \u03B5 \u2212 I\xB7r, where \u03B5 is its EMF (the voltage with no current). The more current is drawn, the bigger the loss \u2014 this is why a flat battery may still show its full voltage on a meter but cannot light a bulb."},check:{title:"Check your understanding",text:"Three 10 \u03A9 bulbs are in series on a 6 V battery. What current flows? (0.2 A.) What voltage does each get? (2 V.) The same bulbs in parallel: what current flows through each? (0.6 A.) Which arrangement shines brighter, and which drains the battery faster? Try each answer in the simulation."}},formula:{ohm:"Ohm's law: current = voltage \xF7 resistance",series:"Resistances in series add up",parallel:"In parallel the inverse resistances add up",seriesVoltage:"In series the voltages add up to the battery voltage",parallelCurrent:"In parallel the branch currents add up to the total",power:"Electric power of a bulb",battery:"Current with the battery's internal resistance r (\u03B5: EMF)"},variable:{voltage:"Voltage",current:"Current",resistance:"Resistance",power:"Power"},assumption:{wires:"The wires have no resistance.",bulbs:"The bulbs keep the same resistance; real filaments change their resistance as they heat up.",battery:"The battery keeps its voltage and internal resistance; it does not run down.",flow:"The moving dots show where and how strongly current flows; real charges drift far more slowly, and their speed is not to scale."},param:{topology:"Connection",voltage:"Battery voltage",removed:"Unscrew a bulb",r1:"Resistance of bulb 1",r2:"Resistance of bulb 2",r3:"Resistance of bulb 3",internal:"Internal resistance of the battery"},hint:{removed:"An unscrewed bulb breaks its path. What happens to the others?",resistance:"A bigger resistance lets less current through.",internal:"Real batteries lose part of their voltage inside when current flows."},preset:{series:"Series",parallel:"Parallel",mixed:"Mixed",aa:"AA battery",flat:"Flat battery",nineVolt:"9 V battery",car:"Car battery",none:"None",bulb1:"Bulb 1",bulb2:"Bulb 2",bulb3:"Bulb 3"},measure:{totalCurrent:"Current from the battery",current1:"Current through bulb 1",current2:"Current through bulb 2",current3:"Current through bulb 3",resistance:"Total resistance",voltage1:"Voltage on bulb 1",voltage2:"Voltage on bulb 2",voltage3:"Voltage on bulb 3",terminalVoltage:"Voltage at the battery terminals",totalPower:"Total power of the bulbs",power1:"Power of bulb 1",power2:"Power of bulb 2",power3:"Power of bulb 3",charge:"Charge passed so far"},view:{removed:"unscrewed",status:"{topology} \xB7 R = {resistance} \xB7 I = {current}",open:"{topology} \xB7 the circuit is broken: no current flows",conventionalFlow:"Dots: current from + to \u2212",electronFlow:"Dots: electrons, moving from \u2212 to +",flowOption:"Moving charges",electronsOption:"Show electrons instead"},graph:{currents:"Bulb currents against time",power:"Total power against time"},challenge:{seriesOut:{title:"All go dark",description:"In a series circuit, unscrew one bulb. What happens to the others?",hint:"Choose Series, then unscrew any bulb."},parallelOn:{title:"The others keep shining",description:"In a parallel circuit, unscrew one bulb so that the other two keep shining.",hint:"Choose Parallel, then unscrew one bulb."},brightest:{title:"Full brightness",description:"Make all three bulbs shine at full brightness.",hint:"Each bulb must get the whole battery voltage."},share:{title:"Half for bulb 1",description:"With at least 9 V in series, give bulb 1 exactly half of the battery voltage.",hint:"Voltage is shared in proportion to resistance: R\u2081 = R\u2082 + R\u2083."},oneAmp:{title:"One ampere",description:"In series, make exactly 1 A flow.",hint:"I = U / (R\u2081 + R\u2082 + R\u2083). For example 12 V and 12 \u03A9 in total."},internal:{title:"A tired battery",description:"Make the voltage at the battery terminals drop below 75 % of its EMF.",hint:"Raise the internal resistance and draw a large current (parallel, small resistances)."}}}},a={sim:r};export{a as default,r as sim};
